#!/bin/bash
curl -s -A 'EmberCorpusResearch/1.0' -m 90 -G "https://archive.org/advancedsearch.php" --data-urlencode "q=$1" --data-urlencode "fl[]=identifier" --data-urlencode "fl[]=title" --data-urlencode "fl[]=date" --data-urlencode "fl[]=language" --data-urlencode "fl[]=creator" --data-urlencode "rows=${2:-100}" --data-urlencode "output=json" | python3 -I -c "import json,sys; [print(d['identifier'],'|',str(d.get('date',''))[:4],'|',str(d.get('language','')),'|',str(d.get('creator',''))[:50],'|',str(d.get('title',''))[:130]) for d in json.load(sys.stdin)['response']['docs']]"
